var ref = document.referrer; var query = document.location.search; if (ref.indexOf("/resources/portal.html") != -1 || query == "?ref=eaRes") {  document.write('<link href="/xtras/portal.css" rel="stylesheet" type="text/css" />');   $(document).ready(function() {    if ($('#content-area').get(0) == 'undefined') {      $('#layoutContent').append('<link href="/xtras/portal.css" rel="stylesheet" type="text/css" />');      if ($('#layoutContent').length > 0) $('#layout').replaceWith($('#layoutContent'));    }    else {      $('#content-area').append('<link href="/xtras/portal.css" rel="stylesheet" type="text/css" />');      if ($('#content-area').length > 0) $('#page').replaceWith($('#content-area'));    }    $('a').each(function() { if (this.href.indexOf('/uml_tool_guide/') == -1) this.href += "?ref=eaRes"; });   }); }

