/* track PDF downloads  
$(document).ready(function(){   $("a[href$='pdf']").each(function(index) { pdfLabel = $(this).attr('href').split("/").pop(); pdfOnClick = "ga('send', 'event', 'PDF', 'click','" + pdfLabel + "');"; $(this).attr("onClick", pdfOnClick); });
});*/
$(document).ready(function() {
    $("a[href$='pdf']").each(function(index) {
        var pdfLabel = $(this).attr('href').split("/").pop();
        var pdfEventName = pdfLabel.replace('.pdf', '-pdf-download');
        var pdfOnClick = "gtag('event', '" + pdfEventName + "', { 'event_category': 'download', 'event_label': '" + pdfLabel + "' });";
        $(this).attr("onClick", pdfOnClick);
    });
});
	
	